analyze.mjs.text:
// Classifies a probe result (real HTTP responses, collected by probe.mjs's
// live network requests or pasted in by hand) against the same criteria
// Chrome's own "installable-manifest" Lighthouse audit checks -- see
// https://developer.chrome.com/docs/lighthouse/pwa/installable-manifest/ and
// https://developer.chrome.com/docs/webapps/manifest -- so a report from this
// tool and a Lighthouse report should never disagree about whether a manifest
// clears the bar.
//
// Pure function, no I/O, no network -- this is the module both the CLI
// (check.mjs, which fetches for real) and the browser page (index.html,
// which can only ever analyse a payload someone already fetched) import, so
// the classification logic exists exactly once.
//
// Why the browser can't fetch this itself for an arbitrary third-party URL:
// a page hosted on this tool's own origin calling fetch() against
// `https://someone-elses-site.example/` is a cross-origin request, and it is
// blocked unless that site's own server opts in with an
// Access-Control-Allow-Origin response header. Most sites do not send CORS
// headers on their HTML page or their manifest.json (there is no reason for
// them to), so a browser-only version of this tool would fail to read the
// response for almost every real page anyone would want to check. Only a
// non-browser HTTP client (this CLI, curl, Lighthouse's own Chrome instance)
// is not subject to that restriction. See README.md and index.html's FAQ.
//
// The checks below, and why each is graded the way it is:
//
//   no-manifest-link        No `<link rel="manifest">` in the page HTML at
//                            all. Chrome will never offer to install a page
//                            with no manifest -- the single hardest blocker.
//   manifest-unreachable     The link points somewhere that doesn't answer
//                            with a successful response.
//   manifest-not-json       The response isn't parseable JSON.
//   missing-name             Neither `name` nor `short_name` is set. Chrome's
//                            install criteria require at least one.
//   missing-display          `display` is absent (defaults to "browser" per
//                            spec) or set to a value other than `standalone`,
//                            `fullscreen`, or `minimal-ui`. A `browser`
//                            display is explicitly excluded from Chrome's
//                            install criteria.
//   insecure-origin          The page is not served over HTTPS (localhost is
//                            exempt, matching the spec's secure-context rule
//                            developers rely on daily). Installability
//                            requires a secure context.
//   missing-192-icon         No icon in the manifest is at least 192x192 (or
//                            declares `sizes: "any"`). Chrome's criteria
//                            require one.
//   missing-512-icon         (notice) No icon is at least 512x512. Not a hard
//                            install blocker, but Chrome uses one for a
//                            richer install/splash UI when present.
//   icon-unreachable          (per icon) An icon URL the manifest lists did
//                            not respond successfully or didn't come back as
//                            an image.
//   missing-start-url         (notice) No explicit `start_url` -- defaults to
//                            the manifest's own document URL, which usually
//                            works but is rarely what you meant.
//   missing-theme-colors      (notice) No `theme_color`/`background_color` --
//                            cosmetic only, affects the splash screen and
//                            browser UI tinting, never installability itself.

const REQUIRED_DISPLAY_MODES = new Set(['standalone', 'fullscreen', 'minimal-ui']);

function safeProtocol(urlString) {
  try {
    return new URL(urlString).protocol;
  } catch {
    return '(unknown)';
  }
}

function parseSizes(sizesAttr) {
  if (typeof sizesAttr !== 'string') return [];
  if (sizesAttr.trim().toLowerCase() === 'any') return ['any'];
  return sizesAttr
    .split(/\s+/)
    .map((s) => {
      const m = /^(\d+)x(\d+)$/i.exec(s.trim());
      return m ? Math.min(Number(m[1]), Number(m[2])) : null;
    })
    .filter((n) => n !== null);
}

function iconMeetsMinSize(icon, minPx) {
  const sizes = parseSizes(icon.sizes);
  if (sizes.includes('any')) return true;
  return sizes.some((s) => s >= minPx);
}

function isReachableImage(icon) {
  if (!icon.fetch || icon.fetch.ok !== true) return false;
  if (icon.fetch.status == null || icon.fetch.status < 200 || icon.fetch.status >= 300) return false;
  const type = (icon.fetch.contentType || '').toLowerCase();
  // Some servers omit or misreport content-type on static assets; only flag
  // it when a content-type is present and clearly isn't an image, rather than
  // demanding one exist.
  if (type && !type.includes('image')) return false;
  return true;
}

/**
 * @param {string} pageUrl
 * @param {ReturnType<import('./probe.mjs').runProbe>} probe - already-awaited
 *   probe result, or an equivalent object pasted in from the CLI's JSON.
 * @returns {{
 *   target: string, findings: object[], dangerCount: number,
 *   noticeCount: number, ok: boolean, incomplete: boolean,
 *   manifestUrl: string|null, iconCount: number,
 * }}
 */
export function buildReport(pageUrl, probe) {
  const p = probe && typeof probe === 'object' ? probe : {};
  const findings = [];
  let incomplete = false;

  if (!p.page || p.page.ok === false) {
    incomplete = true;
    findings.push({
      id: 'page-unreachable',
      severity: 'danger',
      title: 'The page itself could not be fetched',
      detail: `Fetching ${pageUrl} failed: ${p.page?.error ?? 'unknown error'}. None of the manifest checks below could run.`,
      evidence: p.page?.error ?? 'unknown error',
    });
    return finish(pageUrl, findings, incomplete, null, 0);
  }

  if (p.secure === false) {
    findings.push({
      id: 'insecure-origin',
      severity: 'danger',
      title: 'Page is not served over HTTPS',
      detail:
        'Installability requires a secure context. Browsers will not offer to install a page ' +
        'served over plain HTTP (localhost is exempt during development).',
      evidence: `page URL scheme: ${safeProtocol(pageUrl)}`,
    });
  }

  if (!p.manifestHref) {
    findings.push({
      id: 'no-manifest-link',
      severity: 'danger',
      title: 'No <link rel="manifest"> found on the page',
      detail:
        'A page needs a <link rel="manifest"> tag (with a manifest URL in its href attribute) ' +
        'before a browser will consider it installable. None was found in the fetched HTML.',
      evidence: 'no <link rel="manifest"> tag in page HTML',
    });
    return finish(pageUrl, findings, incomplete, null, 0);
  }

  if (!p.manifest || p.manifest.ok === false || (p.manifest.status ?? 0) < 200 || (p.manifest.status ?? 0) >= 300) {
    incomplete = true;
    findings.push({
      id: 'manifest-unreachable',
      severity: 'danger',
      title: 'The manifest link did not resolve to a usable file',
      detail: `<link rel="manifest"> points at ${p.manifestUrl ?? p.manifestHref}, which did not respond successfully (${p.manifest?.error ?? `HTTP ${p.manifest?.status}`}).`,
      evidence: p.manifest?.error ?? `HTTP ${p.manifest?.status}`,
    });
    return finish(pageUrl, findings, incomplete, p.manifestUrl ?? null, 0);
  }

  if (!p.manifestJson) {
    findings.push({
      id: 'manifest-not-json',
      severity: 'danger',
      title: 'The manifest is not valid JSON',
      detail: `${p.manifestUrl} responded successfully but its body did not parse as JSON: ${p.parseError ?? 'unknown parse error'}.`,
      evidence: p.parseError ?? 'unknown parse error',
    });
    return finish(pageUrl, findings, incomplete, p.manifestUrl ?? null, 0);
  }

  const manifest = p.manifestJson;

  if (!manifest.name && !manifest.short_name) {
    findings.push({
      id: 'missing-name',
      severity: 'danger',
      title: 'Manifest has neither "name" nor "short_name"',
      detail: 'Chrome\'s install criteria require at least one of "name" or "short_name" to be set.',
      evidence: 'name and short_name both absent',
    });
  }

  const display = typeof manifest.display === 'string' ? manifest.display.toLowerCase() : null;
  if (!display) {
    findings.push({
      id: 'missing-display',
      severity: 'danger',
      title: 'Manifest has no "display" field',
      detail:
        'With no "display" field the spec default is "browser", which is explicitly excluded ' +
        'from Chrome\'s install criteria -- set "display" to "standalone", "fullscreen", or ' +
        '"minimal-ui".',
      evidence: 'display: (absent, defaults to "browser")',
    });
  } else if (!REQUIRED_DISPLAY_MODES.has(display)) {
    findings.push({
      id: 'missing-display',
      severity: 'danger',
      title: `"display" is set to "${manifest.display}", which is not installable`,
      detail:
        'Chrome only offers to install a page whose manifest "display" is "standalone", ' +
        '"fullscreen", or "minimal-ui".',
      evidence: `display: ${manifest.display}`,
    });
  }

  const icons = Array.isArray(p.icons) ? p.icons : [];
  const hasAny192 = icons.some((icon) => iconMeetsMinSize(icon, 192) && isReachableImage(icon));
  const hasAny512 = icons.some((icon) => iconMeetsMinSize(icon, 512) && isReachableImage(icon));

  if (icons.length === 0) {
    findings.push({
      id: 'missing-192-icon',
      severity: 'danger',
      title: 'Manifest lists no icons at all',
      detail: 'Chrome\'s install criteria require at least one icon of 192x192 or larger (or sizes: "any").',
      evidence: 'icons: (absent or empty)',
    });
  } else if (!hasAny192) {
    findings.push({
      id: 'missing-192-icon',
      severity: 'danger',
      title: 'No reachable icon is at least 192x192',
      detail:
        'Chrome requires at least one icon of 192x192 or larger that actually loads. The icons ' +
        'listed are either smaller, unreachable, or not images.',
      evidence: icons.map((i) => `${i.src ?? '(no src)'} sizes=${i.sizes ?? '?'} status=${i.fetch?.status ?? i.fetch?.error}`).join('; '),
    });
  } else if (!hasAny512) {
    findings.push({
      id: 'missing-512-icon',
      severity: 'notice',
      title: 'No reachable icon is at least 512x512',
      detail:
        'Not a hard installability blocker, but Chrome uses a 512x512-or-larger icon for a ' +
        'richer install dialog and splash screen when one is present.',
      evidence: icons.map((i) => `${i.src ?? '(no src)'} sizes=${i.sizes ?? '?'}`).join('; '),
    });
  }

  for (const icon of icons) {
    if (isReachableImage(icon)) continue;
    findings.push({
      id: 'icon-unreachable',
      severity: 'danger',
      title: `Icon did not load: ${icon.src ?? '(no src)'}`,
      detail: icon.resolvedUrl
        ? `${icon.resolvedUrl} responded with ${icon.fetch?.error ?? `HTTP ${icon.fetch?.status}, content-type ${icon.fetch?.contentType ?? '(none)'}`}.`
        : 'This icon entry has no usable "src", so it could not be fetched at all.',
      evidence: icon.fetch?.error ?? `status=${icon.fetch?.status ?? 'n/a'} content-type=${icon.fetch?.contentType ?? 'n/a'}`,
    });
  }

  if (!manifest.start_url) {
    findings.push({
      id: 'missing-start-url',
      severity: 'notice',
      title: 'Manifest has no explicit "start_url"',
      detail:
        'Not a hard blocker -- it defaults to the manifest\'s own document URL -- but an explicit ' +
        '"start_url" is recommended so the installed app opens where you intend, not wherever the ' +
        'manifest happened to be linked from.',
      evidence: 'start_url: (absent)',
    });
  }

  if (!manifest.theme_color && !manifest.background_color) {
    findings.push({
      id: 'missing-theme-colors',
      severity: 'notice',
      title: 'No "theme_color" or "background_color"',
      detail:
        'Cosmetic only -- these tint the browser UI and splash screen for the installed app. ' +
        'Never a reason installability itself would fail.',
      evidence: 'theme_color and background_color both absent',
    });
  }

  return finish(pageUrl, findings, incomplete, p.manifestUrl ?? null, icons.length);
}

function finish(target, findings, incomplete, manifestUrl, iconCount) {
  const dangerCount = findings.filter((f) => f.severity === 'danger').length;
  const noticeCount = findings.filter((f) => f.severity === 'notice').length;
  return {
    target,
    manifestUrl,
    iconCount,
    findings,
    dangerCount,
    noticeCount,
    ok: !incomplete && dangerCount === 0,
    incomplete,
  };
}

check.mjs.text:
#!/usr/bin/env node
// CLI: fetches a page, its Web App Manifest, and every icon the manifest
// lists, then reports whether it clears Chrome's installability criteria --
// the same checks Lighthouse's "installable-manifest" audit runs, with no
// Chrome/Puppeteer dependency. Your machine, your network -- no request goes
// through this portfolio or anywhere but the URL you pass (and whatever that
// page's own manifest/icons point at).
//
//   node check.mjs <url> [--json] [--timeout <ms>]
//
// This sends ordinary, unauthenticated GET requests -- nothing here bypasses
// authentication or reads protected data -- but treat it the same as you
// would curl or any other request tool aimed at someone else's server.
//
// Exit code 0 when the page is installable by these checks; 1 when at least
// one danger-severity finding is present or the probe could not complete
// (network error, timeout, bad URL).

import { runProbe } from './probe.mjs';
import { buildReport } from './analyze.mjs';

function formatText(report) {
  const lines = [];
  lines.push(`Target: ${report.target}`);
  if (report.manifestUrl) lines.push(`Manifest: ${report.manifestUrl} (${report.iconCount} icon(s) listed)`);
  lines.push('');

  if (report.findings.length === 0) {
    lines.push('No installability issues found by these checks.');
  } else {
    for (const f of report.findings) {
      const mark = f.severity === 'danger' ? '!!' : '--';
      lines.push(`${mark} [${f.severity.toUpperCase()}] ${f.title}`);
      lines.push(`     ${f.detail}`);
      lines.push(`     evidence: ${f.evidence}`);
      lines.push('');
    }
  }

  lines.push(
    report.ok
      ? 'This page clears the checks this tool runs -- the same criteria Lighthouse\'s ' +
        '"installable-manifest" audit checks. See README.md for what it does not check.'
      : 'This is evidence from the checks above, not a full Lighthouse audit -- ' +
        'see README.md for what this tool does and does not check.',
  );
  return lines.join('\n');
}

function parseArgs(argv) {
  const args = { target: null, json: false, timeoutMs: undefined };
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--json') args.json = true;
    else if (argv[i] === '--timeout') args.timeoutMs = Number(argv[++i]);
    else if (!args.target && !argv[i].startsWith('--')) args.target = argv[i];
  }
  return args;
}

/** Pure orchestration: given a probe function (real network, or a stub in
 * tests), fetch and classify. Kept separate from main() so tests can inject
 * a fake `probeFn` instead of hitting the network. */
export async function runCheck(target, { probeFn = runProbe, timeoutMs } = {}) {
  const probe = await probeFn(target, timeoutMs ? { timeoutMs } : {});
  return { report: buildReport(target, probe), probe };
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (!args.target) {
    console.error('Usage: node check.mjs <url> [--json] [--timeout <ms>]');
    process.exit(2);
  }
  try {
    // eslint-disable-next-line no-new
    new URL(args.target);
  } catch {
    console.error(`Not a valid URL: ${args.target}`);
    process.exit(2);
  }

  const { report, probe } = await runCheck(args.target, { timeoutMs: args.timeoutMs });

  if (args.json) {
    console.log(JSON.stringify({ target: report.target, probe }, null, 2));
  } else {
    console.log(formatText(report));
  }
  process.exit(report.ok ? 0 : 1);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

probe.mjs.text:
// Fetches the real, live data this check depends on: the page's HTML (to
// find its `<link rel="manifest">`), the manifest.json it points at, and
// each icon URL the manifest lists. Everything here is a plain, unauthenticated
// GET request using Node's built-in fetch() -- no browser, no headless
// Chrome, no Lighthouse/Puppeteer dependency.
//
// This module only ever talks to the one page URL a caller names, the
// manifest URL that page's own HTML names, and the icon URLs that manifest
// itself lists. It makes no other network call, reads no local files, and
// sends nothing anywhere else.

const DEFAULT_TIMEOUT_MS = 10_000;
const USER_AGENT =
  'pwa-installability-check/1 (+https://duncan-haywood.github.io/monorepo-projects/pwa-installability-check/)';

async function fetchText(url, { timeoutMs = DEFAULT_TIMEOUT_MS } = {}) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const res = await fetch(url, {
      method: 'GET',
      redirect: 'follow',
      headers: { 'user-agent': USER_AGENT, accept: '*/*' },
      signal: controller.signal,
    });
    const body = await res.text();
    return {
      ok: true,
      status: res.status,
      contentType: res.headers.get('content-type') ?? null,
      finalUrl: res.url || url,
      body,
      error: null,
    };
  } catch (err) {
    return { ok: false, status: null, contentType: null, finalUrl: url, body: null, error: err.message };
  } finally {
    clearTimeout(timer);
  }
}

/**
 * A lightweight existence/type check for an icon URL: does it respond, with
 * what status, and what content-type. Reads and discards the body (some
 * servers answer HEAD with a 405 or lie about content-length on HEAD, so a
 * real GET is the more honest signal here; icons are small).
 */
async function fetchIconMeta(url, { timeoutMs = DEFAULT_TIMEOUT_MS } = {}) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const res = await fetch(url, {
      method: 'GET',
      redirect: 'follow',
      headers: { 'user-agent': USER_AGENT, accept: 'image/*,*/*' },
      signal: controller.signal,
    });
    // Drain the body without holding it all in memory unnecessarily.
    if (res.body) {
      // eslint-disable-next-line no-unused-vars
      for await (const _chunk of res.body) {
        /* discard */
      }
    }
    return {
      ok: true,
      status: res.status,
      contentType: res.headers.get('content-type') ?? null,
      error: null,
    };
  } catch (err) {
    return { ok: false, status: null, contentType: null, error: err.message };
  } finally {
    clearTimeout(timer);
  }
}

/** First `<link rel="manifest">` tag's href in `html`, case- and
 * attribute-order-insensitive. Returns the raw href string, unresolved. */
export function findManifestHref(html) {
  const linkRe = /<link\b[^>]*>/gi;
  let match;
  while ((match = linkRe.exec(html)) !== null) {
    const tag = match[0];
    if (!/rel\s*=\s*["']?\s*manifest\s*["']?/i.test(tag)) continue;
    const hrefMatch = /href\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i.exec(tag);
    if (!hrefMatch) continue;
    return hrefMatch[1] ?? hrefMatch[2] ?? hrefMatch[3] ?? null;
  }
  return null;
}

/**
 * Runs the full probe against `pageUrl`: fetches the page, finds and fetches
 * the manifest, parses it, and fetches every icon it lists. Never throws --
 * every stage that can fail records its own `ok`/`error` and the pipeline
 * stops cleanly at the first missing link, since nothing later than a
 * missing manifest can be checked at all.
 */
export async function runProbe(pageUrl, opts = {}) {
  let target;
  try {
    target = new URL(pageUrl);
  } catch (err) {
    return {
      pageUrl,
      secure: null,
      page: { ok: false, status: null, error: `invalid URL: ${err.message}` },
      manifestHref: null,
      manifestUrl: null,
      manifest: { ok: false, status: null, error: null },
      manifestJson: null,
      parseError: null,
      icons: [],
    };
  }

  const secure = target.protocol === 'https:' || target.hostname === 'localhost' || target.hostname === '127.0.0.1';

  const page = await fetchText(pageUrl, opts);
  const result = {
    pageUrl,
    secure,
    page: { ok: page.ok, status: page.status, contentType: page.contentType, error: page.error },
    manifestHref: null,
    manifestUrl: null,
    manifest: { ok: false, status: null, contentType: null, error: null },
    manifestJson: null,
    parseError: null,
    icons: [],
  };

  if (!page.ok) return result;

  const manifestHref = findManifestHref(page.body ?? '');
  result.manifestHref = manifestHref;
  if (!manifestHref) return result;

  let manifestUrl;
  try {
    manifestUrl = new URL(manifestHref, page.finalUrl || pageUrl).toString();
  } catch (err) {
    result.parseError = `manifest href is not a resolvable URL: ${err.message}`;
    return result;
  }
  result.manifestUrl = manifestUrl;

  const manifest = await fetchText(manifestUrl, opts);
  result.manifest = { ok: manifest.ok, status: manifest.status, contentType: manifest.contentType, error: manifest.error };
  if (!manifest.ok || manifest.status < 200 || manifest.status >= 300) return result;

  let json;
  try {
    json = JSON.parse(manifest.body);
  } catch (err) {
    result.parseError = err.message;
    return result;
  }
  result.manifestJson = json;

  const iconEntries = Array.isArray(json.icons) ? json.icons : [];
  result.icons = await Promise.all(
    iconEntries.map(async (icon) => {
      const src = typeof icon?.src === 'string' ? icon.src : null;
      let resolvedUrl = null;
      let resolveError = null;
      if (src) {
        try {
          resolvedUrl = new URL(src, manifestUrl).toString();
        } catch (err) {
          resolveError = err.message;
        }
      }
      const fetchResult = resolvedUrl
        ? await fetchIconMeta(resolvedUrl, opts)
        : { ok: false, status: null, contentType: null, error: resolveError ?? 'no src' };
      return {
        src,
        resolvedUrl,
        sizes: typeof icon?.sizes === 'string' ? icon.sizes : null,
        type: typeof icon?.type === 'string' ? icon.type : null,
        purpose: typeof icon?.purpose === 'string' ? icon.purpose : null,
        fetch: fetchResult,
      };
    }),
  );

  return result;
}

usage.mjs.text:
// Records an anonymous, aggregate-only local usage count: the event name and
// the current day, kept in the visitor's own browser. It never stores the
// target URL, the pasted probe JSON, or anything about what was checked --
// that is exactly the kind of thing that must not be transmitted anywhere,
// and this tool never reads it off the visitor's machine either.

const STORAGE_KEY = 'pwa-installability-check-usage';

function honorsBrowserSignal() {
  try {
    return globalThis.navigator?.doNotTrack === '1' || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(storage = globalThis.localStorage, optedOut = false, event = 'check_run') {
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  try {
    const today = new Date().toISOString().slice(0, 10);
    const current = JSON.parse(storage.getItem(STORAGE_KEY) || '{}');
    current[event] = (current[event] || 0) + 1;
    current.last_day = today;
    storage.setItem(STORAGE_KEY, JSON.stringify(current));
  } catch {
    // A browser refusing site data must not stop the page computing a result.
  }
}

// The opt-out choice is kept in its own key, not in the counters:
// opting out *removes* the counters, so a flag stored inside them would
// be deleted by the very act it records. `recordUsage` above consults it
// directly as well as taking the caller's argument -- a stored preference
// that only one line of page wiring reads is one line away from being
// forgotten, which is the defect this change exists to fix.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem(`${STORAGE_KEY}-opt-out`) === '1';
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  // Independent writes, counters first: sharing one try means a setItem
  // that throws on a full quota skips the delete entirely, and the
  // visitor gets neither half of what the control promised.
  if (optedOut) {
    try { storage.removeItem(STORAGE_KEY); } catch { /* storage is optional */ }
    try { storage.setItem(`${STORAGE_KEY}-opt-out`, '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem(`${STORAGE_KEY}-opt-out`); } catch { /* storage is optional */ }
  }
}
